const body = $json.body ?? $json;
const errors = [];
const allowed = new Set(['unit_id','topic_name','raw_content','standard_id','request_id']);
for (const key of Object.keys(body)) if (!allowed.has(key)) errors.push(`unexpected field: ${key}`);
if (!Number.isInteger(body.unit_id) || body.unit_id <= 0 || body.unit_id > 1000000) errors.push('unit_id must be a positive integer');
const topic = typeof body.topic_name === 'string' ? body.topic_name.trim() : '';
if (topic.length < 2 || topic.length > 200) errors.push('topic_name must be 2-200 characters');
const raw = typeof body.raw_content === 'string' ? body.raw_content.trim() : '';
if (raw.length < 20 || raw.length > 20000) errors.push('raw_content must be 20-20000 characters');
const standards = new Set([100,101,102,200,300,400,401,402,403,404]);
if (!Number.isInteger(body.standard_id) || !standards.has(body.standard_id)) errors.push('unsupported standard_id');
if (body.request_id !== undefined && (typeof body.request_id !== 'string' || !/^[A-Za-z0-9._:-]{8,120}$/.test(body.request_id.trim()))) errors.push('request_id is invalid');
const unsafe = [/ignore\s+(?:all\s+)?previous\s+instructions/i,/reveal\s+(?:the\s+)?(?:system|developer)\s+prompt/i,/(?:system|developer)\s+message\s*:/i,/jailbreak/i,/\b(?:api[_ -]?key|access[_ -]?token|password|secret)\s*[:=]/i,/\b\d{3}-\d{2}-\d{4}\b/,/\b(?:MRN|medical record number)\s*[:#]?\s*[A-Za-z0-9-]{4,}\b/i,/\b(?:date of birth|DOB)\s*[:#]?\s*\d{1,2}[\/-]\d{1,2}[\/-]\d{2,4}\b/i,/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i];
if (unsafe.some((pattern) => pattern.test(raw))) errors.push('raw_content contains prompt injection, credentials, PHI, or contact data');
const state = $getWorkflowStaticData('global');
const minute = Math.floor(Date.now() / 60000);
if (state.minute !== minute) { state.minute = minute; state.count = 0; }
state.count = Number(state.count || 0) + 1;
if (state.count > 30) return [{json:{valid:false,statusCode:429,errors:['webhook rate limit reached']}}];
return [{json:{valid:errors.length===0,statusCode:400,errors,source:{unit_id:body.unit_id,topic_name:topic,raw_content:raw,standard_id:body.standard_id,...(body.request_id ? {request_id:body.request_id.trim()} : {})}}}];

const source = $('Validate Input and Rate Limit').item.json.source;
const generated = $json.output ?? $json;
const issues = [];
if ($json.error || !generated || typeof generated !== 'object') return [{json:{qa_passed:false,status_code:503,issues:['Gemini provider or parser failure']}}];
const expected = new Set(['question_stem','options','video_script','keyword_to_highlight','caption','cta']);
for (const key of Object.keys(generated)) if (!expected.has(key)) issues.push(`unexpected generated field: ${key}`);
if (!Array.isArray(generated.options) || generated.options.length !== 4) issues.push('exactly four options are required');
const options = Array.isArray(generated.options) ? generated.options : [];
const texts = options.map(o => String(o.option_text || '').trim().replace(/\s+/g,' ').toLowerCase());
if (texts.some(t => !t) || new Set(texts).size !== 4) issues.push('options must be nonempty and distinct');
const correct = options.filter(o => o.is_correct === true);
if (correct.length !== 1) issues.push('exactly one option must be correct');
for (const option of options) { const rationale=String(option.rationale_text||''); if (!rationale.trim()) issues.push('all rationales are required'); if (option.is_correct && /\b(?:incorrect|not (?:the )?correct|should not)\b/i.test(rationale)) issues.push('correct rationale contradicts answer'); if (!option.is_correct && /\b(?:is|this is) (?:the )?correct\b/i.test(rationale)) issues.push('incorrect rationale contradicts answer'); }
const script=String(generated.video_script?.asset_content||'').trim();
const words=script.split(/\s+/).filter(Boolean).length;
if (words < 25 || words > 30) issues.push('asset_content must be 25-30 words');
const text=JSON.stringify(generated);
const prohibited=[/https?:\/\//i,/```/,/^\s{0,3}#{1,6}\s/m,/ignore\s+(?:all\s+)?previous\s+instructions/i,/reveal\s+(?:the\s+)?(?:system|developer)\s+prompt/i,/\b(?:MRN|medical record number)\s*[:#]?\s*[A-Za-z0-9-]{4,}\b/i,/\b\d{3}-\d{2}-\d{4}\b/,/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i];
if (prohibited.some(p=>p.test(text))) issues.push('output contains URL, markdown, injection language, or sensitive data');
const numberPattern=/\b\d+(?:\.\d+)?\s*(?:mg|mcg|g|kg|mL|L|mEq|mmHg|bpm|%|seconds?|minutes?|hours?|days?|\/\s*(?:dL|L|mm3|mm³|mcL))\b/gi;
const norm=s=>s.trim().replace(/\s+/g,' ').toLowerCase();
const sourceNumbers=new Set(Array.from(source.raw_content.matchAll(numberPattern),m=>norm(m[0])));
const generatedNumbers=Array.from(text.matchAll(numberPattern),m=>norm(m[0]));
const unsupported=[...new Set(generatedNumbers.filter(n=>!sourceNumbers.has(n)))];
if (unsupported.length) issues.push(`unsupported clinical numbers: ${unsupported.join(', ')}`);
return [{json:{qa_passed:issues.length===0,status_code:422,issues,payload:{...source,request_id:$('Application Preflight').item.json.body.request_id,generated}}}];
